const stdout = $input.first().json.stdout;

// Use regex to find the English Challan No line
const match = stdout.match(/Translated English Challan No:\s*([0-9\-]+)/);
const englishChallanNo = match ? match[1].trim() : null;

return {
  json: {
    english_challan_no: englishChallanNo
  }
};

const result = JSON.parse($input.first().json.stdout);

return {
  json: result
};

const inputItem = $input.first().json;

// 1. Unify and search text from any possible input structure
let text = "";
if (inputItem.text) {
    text = inputItem.text;
} else if (inputItem.parts && Array.isArray(inputItem.parts)) {
    text = inputItem.parts.map(p => p.text || "").join("\n");
} else {
    text = JSON.stringify(inputItem);
}

// 2. Extract English Challan No
let englishChallanNo = inputItem.english_challan_no || null;
if (!englishChallanNo) {
    const challanMatch = text.match(/Translated English Challan No:\s*([0-9\-]+)/i);
    englishChallanNo = challanMatch ? challanMatch[1].trim() : null;
}

// 3. Extract Date (Checks JSON keys, standard text labels, and DD/MM/YYYY formats)
const dateMatch = 
    text.match(/"date"\s*:\s*"([^"]+)"/i) || 
    text.match(/date\s*[:=]\s*["']?([^"'\n\r]+)["']?/i) ||
    text.match(/তারিখ\s*[:\s]*([0-9\/]{8,10})/i) ||
    text.match(/\b([0-9]{4}-[0-9]{2}-[0-9]{2})\b/);

const date = dateMatch ? dateMatch[1].trim() : null;

// 4. Extract TDS Amount
const tdsMatch = text.match(/"dhl_tds_amount"\s*:\s*"([^"]+)"/i) || text.match(/TDS[^0-9]*([0-9,]+\.[0-9]{2})/i);
const tdsAmount = tdsMatch ? tdsMatch[1].trim() : null;

// 5. Extract Total Amount
const totalMatch = text.match(/"total_amount"\s*:\s*"([^"]+)"/i) || text.match(/Total[^0-9]*([0-9,]+\.[0-9]{2})/i);
const totalAmount = totalMatch ? totalMatch[1].trim() : null;

return {
  json: {
    english_challan_no: englishChallanNo,
    date: date,
    dhl_tds_amount: tdsAmount,
    total_amount: totalAmount
  }
};

const existingRows = $input.all()
  .map(item => item.json)
  .filter(row =>
    Object.values(row).some(
      value => value !== null &&
               value !== undefined &&
               String(value).trim() !== ""
    )
  );

// Get the newly extracted challan record
const newRecord = $('Code in JavaScript2').first().json;

// Combine existing records with the new record
const allRecords = [...existingRows, newRecord];

// Keep exactly five Excel columns (checking both challan field name variants)
return allRecords.map(row => ({
  json: {
    challan_no: row.challan_no || row.english_challan_no || "",
    date: row.date || "",
    total_amount: row.total_amount || "",
    dhl_tds_amount: row.dhl_tds_amount || "",
    confidence_level: row.confidence_level ?? ""
  }
}));

const result = JSON.parse($input.first().json.stdout);

return {
  json: result
};
